import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { describe, expect, it } from 'vitest';

import { analyzeInput } from '../src/lib/certificate';
import { decodeInput } from '../src/lib/certificate/decode-input';
import { detectDerShape } from '../src/lib/certificate/detect-format';
import { bytesToBase64 } from '../src/lib/certificate/encoding';
import { decodePkcs12 } from '../src/lib/certificate/pkcs12';

/** Generated by tests/fixtures/pkcs12/generate.sh with the OpenSSL CLI. */
function pfx(name: string): Uint8Array {
  return new Uint8Array(readFileSync(join(__dirname, 'fixtures/pkcs12', `${name}.p12`)));
}

const codes = (issues: { code: string }[]) => issues.map((issue) => issue.code);

describe('PKCS#12 detection', () => {
  it('is recognised by shape and handed on undecoded', () => {
    const bytes = pfx('modern');
    expect(detectDerShape(bytes)).toBe('pkcs12');

    const result = decodeInput(bytes);
    expect(result.detectedFormat).toBe('pkcs12');
    expect(result.detectedFormatLabel).toBe('PKCS#12 / PFX');
    expect(result.pkcs12).toEqual(bytes);
    expect(result.blocks).toEqual([]);
    expect(result.issues).toEqual([]);
  });

  it('is found inside Base64, as Key Vault and CI secrets store it', () => {
    const result = decodeInput(bytesToBase64(pfx('modern')));
    expect(result.detectedFormat).toBe('pkcs12');
    expect(result.pkcs12).toBeDefined();
  });
});

describe('PBES2 containers (OpenSSL 3 default)', () => {
  it('extracts the certificates with the right password', async () => {
    const contents = await decodePkcs12(pfx('modern'), 'secret');

    expect(contents.certificates).toHaveLength(2);
    expect(contents.passwordRequired).toBe(false);
    expect(contents.containsPrivateKey).toBe(false);
    expect(codes(contents.issues)).toEqual(['PKCS12_ENCRYPTED_KEY']);
  });

  it('asks for a password when none is given', async () => {
    const contents = await decodePkcs12(pfx('modern'));

    expect(contents.certificates).toEqual([]);
    expect(contents.passwordRequired).toBe(true);
    expect(codes(contents.issues)).toContain('PKCS12_PASSWORD_REQUIRED');
    expect(codes(contents.issues)).not.toContain('NO_CERTIFICATE_FOUND');
  });

  it('reports a wrong password without throwing', async () => {
    const contents = await decodePkcs12(pfx('modern'), 'wrong');

    expect(contents.certificates).toEqual([]);
    expect(contents.passwordRequired).toBe(true);
    expect(contents.issues[0]).toMatchObject({
      severity: 'error',
      code: 'PKCS12_WRONG_PASSWORD',
    });
  });

  it('handles non-ASCII passwords', async () => {
    const contents = await decodePkcs12(pfx('unicode-password'), 'zażółć');
    expect(contents.certificates).toHaveLength(2);
    expect(contents.passwordRequired).toBe(false);
  });

  it('opens a file exported with an empty password without asking', async () => {
    const contents = await decodePkcs12(pfx('empty-password'));
    expect(contents.certificates).toHaveLength(2);
    expect(contents.passwordRequired).toBe(false);
  });
});

describe('other PKCS#12 layouts', () => {
  it('shows unencrypted certificates before the password is known', async () => {
    const contents = await decodePkcs12(pfx('plain-certs'));

    expect(contents.certificates).toHaveLength(2);
    // The MAC still needs the password, so the file is not verified yet.
    expect(contents.passwordRequired).toBe(true);
    expect(contents.issues.find((i) => i.code === 'PKCS12_PASSWORD_REQUIRED')?.detail).toContain(
      'not been verified',
    );

    const verified = await decodePkcs12(pfx('plain-certs'), 'secret');
    expect(verified.certificates).toHaveLength(2);
    expect(verified.passwordRequired).toBe(false);
  });

  it('detects a wrong password by failed decryption when there is no MAC', async () => {
    const wrong = await decodePkcs12(pfx('no-mac'), 'wrong');
    expect(wrong.certificates).toEqual([]);
    expect(codes(wrong.issues)).toEqual(
      expect.arrayContaining(['PKCS12_NO_MAC', 'PKCS12_WRONG_PASSWORD']),
    );

    const right = await decodePkcs12(pfx('no-mac'), 'secret');
    expect(right.certificates).toHaveLength(2);
    expect(codes(right.issues)).not.toContain('PKCS12_WRONG_PASSWORD');
  });

  it('names the legacy RC2 scheme instead of asking for a password', async () => {
    const contents = await decodePkcs12(pfx('legacy'));

    expect(contents.passwordRequired).toBe(false);
    const issue = contents.issues.find((i) => i.code === 'PKCS12_UNSUPPORTED');
    expect(issue?.message).toContain('pbeWithSHAAnd40BitRC2-CBC');
    expect(issue?.detail).toContain('openssl pkcs12');
  });

  it('reports garbage that only looks like a PFX', async () => {
    const contents = await decodePkcs12(new Uint8Array([0x30, 0x03, 0x02, 0x01, 0x03]));
    expect(codes(contents.issues)).toEqual(['PARSE_FAILED']);
  });
});

describe('PKCS#12 end to end', () => {
  it('builds and verifies the chain stored in the PFX', async () => {
    const { decode, chain } = await analyzeInput(pfx('modern'), { password: 'secret' });

    expect(decode.detectedFormat).toBe('pkcs12');
    expect(decode.passwordRequired).toBe(false);
    expect(decode.blocks.every((block) => block.via === 'pkcs12')).toBe(true);
    expect(chain.certificates.map((c) => c.role)).toEqual(['leaf', 'root']);
    expect(chain.cryptographicStatus).toBe('valid');
  });

  it('surfaces the password prompt through analyzeInput', async () => {
    const { decode, chain } = await analyzeInput(pfx('modern'));

    expect(decode.passwordRequired).toBe(true);
    expect(chain.certificates).toEqual([]);
    expect(codes(decode.issues)).toEqual(['PKCS12_PASSWORD_REQUIRED', 'PKCS12_ENCRYPTED_KEY']);
  });
});
